-- DGDB Lab 2 transaction seed. Run once as DGDB in FREEPDB1 after 002.
-- NOT RERUNNABLE: order numbers and payment references are unique.
-- Identity values are generated by Oracle; customer email, product SKU, and
-- order number are the stable keys used to resolve foreign keys.
-- Checkout reservations use execution time so they are active on completion
-- for roughly ten minutes. Other row content is deterministic.
-- Troubleshooting: INSERT ALL from one DUAL source row can reuse an Oracle
-- identity value across INTO clauses, causing ORA-00001 on the identity PK.
-- Use individual identity-backed inserts, as this script does.

SET DEFINE OFF
WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK

DECLARE
    l_run_at       TIMESTAMP(6) WITH TIME ZONE := SYSTIMESTAMP;
    l_customer_id  customers.customer_id%TYPE;
    l_product_id   products.product_id%TYPE;
    l_order_id     orders.order_id%TYPE;
    l_item_id      order_items.order_item_id%TYPE;
    l_price        products.unit_price%TYPE;
    l_reserved_at  TIMESTAMP(6) WITH TIME ZONE;
    l_amount       orders.total_amount%TYPE;
    l_bad_count    NUMBER;

    PROCEDURE seed_order (
        p_number   IN orders.order_number%TYPE,
        p_email    IN customers.email%TYPE,
        p_sku      IN products.sku%TYPE,
        p_qty      IN order_items.quantity%TYPE,
        p_outcome  IN orders.status%TYPE
    ) IS
    BEGIN
        SELECT customer_id INTO l_customer_id FROM customers WHERE email = p_email;
        SELECT product_id, unit_price INTO l_product_id, l_price
          FROM products WHERE sku = p_sku;
        l_amount := p_qty * l_price;
        l_reserved_at := CASE WHEN p_outcome = 'EXPIRED'
                              THEN l_run_at - INTERVAL '11' MINUTE
                              ELSE l_run_at END;

        INSERT INTO orders (order_number, customer_id, status, subtotal_amount,
                            total_amount, placed_at, created_at, updated_at)
        VALUES (p_number, l_customer_id, 'PENDING', l_amount,
                l_amount, l_reserved_at, l_reserved_at, l_run_at);
        SELECT order_id INTO l_order_id FROM orders WHERE order_number = p_number;

        INSERT INTO order_items (order_id, product_id, quantity, unit_price,
                                 line_total, created_at)
        VALUES (l_order_id, l_product_id, p_qty, l_price, l_amount, l_reserved_at);
        SELECT order_item_id INTO l_item_id FROM order_items
         WHERE order_id = l_order_id AND product_id = l_product_id;

        -- Reserve physical stock without changing ON_HAND_QTY.
        UPDATE inventory
           SET reserved_qty = reserved_qty + p_qty, updated_at = l_run_at
         WHERE product_id = l_product_id
           AND on_hand_qty - reserved_qty >= p_qty;
        IF SQL%ROWCOUNT != 1 THEN
            RAISE_APPLICATION_ERROR(-20001, 'Insufficient inventory for ' || p_sku);
        END IF;
        INSERT INTO reservations (order_item_id, order_id, product_id, quantity,
                                  status, reserved_at, expires_at)
        VALUES (l_item_id, l_order_id, l_product_id, p_qty, 'CHECKOUT',
                l_reserved_at, l_reserved_at + INTERVAL '10' MINUTE);

        IF p_outcome IN ('PAID', 'FULFILLED') THEN
            INSERT INTO payments (order_id, payment_reference, status, amount,
                                  created_at, completed_at)
            VALUES (l_order_id, 'DGDB-SEED-' || p_number, 'SUCCEEDED', l_amount,
                    l_run_at, l_run_at);
            UPDATE reservations SET status = 'ALLOCATED'
             WHERE order_id = l_order_id AND status = 'CHECKOUT';
            UPDATE orders SET status = 'PAID', paid_at = l_run_at,
                              updated_at = l_run_at
             WHERE order_id = l_order_id;
        ELSIF p_number = 'DG-L2-010' THEN
            -- Failed payment leaves its checkout reservation active.
            INSERT INTO payments (order_id, payment_reference, status, amount,
                                  created_at, completed_at)
            VALUES (l_order_id, 'DGDB-SEED-' || p_number, 'FAILED', l_amount,
                    l_run_at, l_run_at);
        END IF;

        IF p_outcome = 'FULFILLED' THEN
            -- Dispatch consumes the paid allocation and physical stock together.
            UPDATE inventory
               SET on_hand_qty = on_hand_qty - p_qty,
                   reserved_qty = reserved_qty - p_qty,
                   updated_at = l_run_at
             WHERE product_id = l_product_id
               AND on_hand_qty >= p_qty AND reserved_qty >= p_qty;
            IF SQL%ROWCOUNT != 1 THEN
                RAISE_APPLICATION_ERROR(-20002, 'Fulfilment balance failed for ' || p_sku);
            END IF;
            INSERT INTO stock_movements (product_id, movement_type,
                                         quantity_delta, reason,
                                         reference_type, reference_id, occurred_at)
            VALUES (l_product_id, 'FULFILMENT', -p_qty,
                    'DGDB seed order dispatch', 'ORDER', l_order_id, l_run_at);
            UPDATE reservations SET status = 'FULFILLED', closed_at = l_run_at
             WHERE order_id = l_order_id AND status = 'ALLOCATED';
            UPDATE orders SET status = 'FULFILLED', fulfilled_at = l_run_at,
                              updated_at = l_run_at
             WHERE order_id = l_order_id;
        ELSIF p_outcome IN ('CANCELLED', 'EXPIRED') THEN
            UPDATE inventory
               SET reserved_qty = reserved_qty - p_qty, updated_at = l_run_at
             WHERE product_id = l_product_id AND reserved_qty >= p_qty;
            IF SQL%ROWCOUNT != 1 THEN
                RAISE_APPLICATION_ERROR(-20003, 'Release balance failed for ' || p_sku);
            END IF;
            UPDATE reservations
               SET status = CASE WHEN p_outcome = 'CANCELLED' THEN 'RELEASED'
                                 ELSE 'EXPIRED' END,
                   closed_at = l_run_at
             WHERE order_id = l_order_id AND status = 'CHECKOUT';
            UPDATE orders
               SET status = p_outcome,
                   cancelled_at = CASE WHEN p_outcome = 'CANCELLED'
                                       THEN l_run_at ELSE NULL END,
                   updated_at = l_run_at
             WHERE order_id = l_order_id;
        END IF;
    END seed_order;
BEGIN
    -- Six dispatched orders; one line item and one reservation per order.
    seed_order('DG-L2-001', 'riley01@example.test',  'DG-DECK-001', 1, 'FULFILLED');
    seed_order('DG-L2-002', 'jordan02@example.test', 'DG-TRK-001',  2, 'FULFILLED');
    seed_order('DG-L2-003', 'casey03@example.test',  'DG-WHL-001',  1, 'FULFILLED');
    seed_order('DG-L2-004', 'taylor04@example.test', 'DG-BRG-001',  2, 'FULFILLED');
    seed_order('DG-L2-005', 'alex05@example.test',   'DG-CMP-001',  1, 'FULFILLED');
    seed_order('DG-L2-006', 'sam06@example.test',    'DG-ACC-001',  3, 'FULFILLED');
    -- Two paid allocations retain RESERVED_QTY until dispatch or cancellation.
    seed_order('DG-L2-007', 'morgan07@example.test', 'DG-DECK-002', 1, 'PAID');
    seed_order('DG-L2-008', 'jamie08@example.test',  'DG-WHL-002',  2, 'PAID');
    -- Two live checkout holds; the second has a failed payment attempt.
    seed_order('DG-L2-009', 'avery09@example.test', 'DG-TRK-002',  1, 'PENDING');
    seed_order('DG-L2-010', 'quinn10@example.test', 'DG-CMP-002',  1, 'PENDING');
    -- One cancelled hold and one expired hold; both release inventory.
    seed_order('DG-L2-011', 'drew11@example.test',  'DG-ACC-003',  2, 'CANCELLED');
    seed_order('DG-L2-012', 'reese12@example.test', 'DG-DECK-003', 1, 'EXPIRED');

    -- The scenario must contain exactly the requested order and payment states.
    SELECT COUNT(*) INTO l_bad_count FROM (
        SELECT status, COUNT(*) AS n FROM orders
         WHERE order_number BETWEEN 'DG-L2-001' AND 'DG-L2-012'
         GROUP BY status
        HAVING (status = 'FULFILLED' AND COUNT(*) = 6)
            OR (status = 'PAID' AND COUNT(*) = 2)
            OR (status = 'PENDING' AND COUNT(*) = 2)
            OR (status = 'CANCELLED' AND COUNT(*) = 1)
            OR (status = 'EXPIRED' AND COUNT(*) = 1)
    );
    IF l_bad_count <> 5 THEN
        RAISE_APPLICATION_ERROR(-20008, 'Seed order state counts differ');
    END IF;

    SELECT COUNT(*) INTO l_bad_count FROM payments p
    JOIN orders o ON o.order_id = p.order_id
    WHERE o.order_number BETWEEN 'DG-L2-001' AND 'DG-L2-012'
      AND ((p.status = 'SUCCEEDED' AND o.status IN ('PAID', 'FULFILLED'))
        OR (p.status = 'FAILED' AND o.order_number = 'DG-L2-010'));
    IF l_bad_count <> 9 THEN
        RAISE_APPLICATION_ERROR(-20009, 'Seed payments differ');
    END IF;

    -- Abort the transaction if a checkout hold expired during execution.
    SELECT COUNT(*) INTO l_bad_count
      FROM reservations r JOIN orders o ON o.order_id = r.order_id
     WHERE o.order_number BETWEEN 'DG-L2-001' AND 'DG-L2-012'
       AND r.status = 'CHECKOUT' AND r.expires_at <= SYSTIMESTAMP;
    IF l_bad_count <> 0 THEN
        RAISE_APPLICATION_ERROR(-20004, 'Checkout reservation expired during seed');
    END IF;

    SELECT COUNT(*) INTO l_bad_count FROM (
        SELECT o.order_id FROM orders o JOIN order_items oi ON oi.order_id = o.order_id
         WHERE o.order_number BETWEEN 'DG-L2-001' AND 'DG-L2-012'
         GROUP BY o.order_id, o.subtotal_amount, o.total_amount
        HAVING o.subtotal_amount <> SUM(oi.line_total)
            OR o.total_amount <> SUM(oi.line_total)
    );
    IF l_bad_count <> 0 THEN
        RAISE_APPLICATION_ERROR(-20005, 'Order totals do not reconcile');
    END IF;

    SELECT COUNT(*) INTO l_bad_count FROM (
        SELECT i.product_id FROM inventory i
        LEFT JOIN stock_movements sm ON sm.product_id = i.product_id
        GROUP BY i.product_id, i.on_hand_qty
        HAVING i.on_hand_qty <> NVL(SUM(sm.quantity_delta), 0)
    );
    IF l_bad_count <> 0 THEN
        RAISE_APPLICATION_ERROR(-20006, 'Physical stock differs from ledger');
    END IF;

    SELECT COUNT(*) INTO l_bad_count FROM (
        SELECT i.product_id FROM inventory i
        LEFT JOIN reservations r ON r.product_id = i.product_id
        GROUP BY i.product_id, i.reserved_qty
        HAVING i.reserved_qty <> NVL(SUM(CASE WHEN r.status IN ('CHECKOUT', 'ALLOCATED')
                                              THEN r.quantity ELSE 0 END), 0)
    );
    IF l_bad_count <> 0 THEN
        RAISE_APPLICATION_ERROR(-20007, 'Active allocations differ from reserved stock');
    END IF;
END;
/

-- Read-only verification before the final commit.
-- Each query should return the stated counts or zero discrepancies.
SELECT o.status, COUNT(*) AS order_count
FROM orders o WHERE o.order_number BETWEEN 'DG-L2-001' AND 'DG-L2-012'
GROUP BY o.status ORDER BY o.status;
-- Expected: FULFILLED 6, PAID 2, PENDING 2, CANCELLED 1, EXPIRED 1.

SELECT p.status, COUNT(*) AS payment_count
FROM payments p JOIN orders o ON o.order_id = p.order_id
WHERE o.order_number BETWEEN 'DG-L2-001' AND 'DG-L2-012'
GROUP BY p.status ORDER BY p.status;
-- Expected: SUCCEEDED 8, FAILED 1.

SELECT o.order_number, o.subtotal_amount, o.total_amount,
       SUM(oi.line_total) AS item_total
FROM orders o JOIN order_items oi ON oi.order_id = o.order_id
WHERE o.order_number BETWEEN 'DG-L2-001' AND 'DG-L2-012'
GROUP BY o.order_number, o.subtotal_amount, o.total_amount
HAVING o.subtotal_amount <> SUM(oi.line_total)
    OR o.total_amount <> SUM(oi.line_total);
-- Expected: no rows.

SELECT p.sku, i.on_hand_qty, NVL(SUM(sm.quantity_delta), 0) AS ledger_qty
FROM products p JOIN inventory i ON i.product_id = p.product_id
LEFT JOIN stock_movements sm ON sm.product_id = p.product_id
GROUP BY p.sku, i.on_hand_qty
HAVING i.on_hand_qty <> NVL(SUM(sm.quantity_delta), 0);
-- Expected: no rows if opening receipts and all later physical changes reconcile.

SELECT p.sku, i.reserved_qty,
       NVL(SUM(CASE WHEN r.status IN ('CHECKOUT', 'ALLOCATED')
                    THEN r.quantity ELSE 0 END), 0) AS allocation_qty
FROM products p JOIN inventory i ON i.product_id = p.product_id
LEFT JOIN reservations r ON r.product_id = p.product_id
GROUP BY p.sku, i.reserved_qty
HAVING i.reserved_qty <> NVL(SUM(CASE WHEN r.status IN ('CHECKOUT', 'ALLOCATED')
                                      THEN r.quantity ELSE 0 END), 0);
-- Expected: no rows. Expiry is a state transition, not automatic at expires_at.

COMMIT;
